<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Mail};
use App\Services\Support;
class ReviewController extends Controller {
 public function approve(Request $r,int $id){$v=$r->validate(['decision'=>'required|in:approved,rejected','reason'=>'required_if:decision,rejected|nullable|string|min:10|max:300']);$roles=auth()->user()->role==='admin'?['seller']:['sorting_center'];DB::transaction(function()use($id,$v,$roles){$u=DB::table('users')->where('id',$id)->whereIn('role',$roles)->lockForUpdate()->first();abort_unless($u&&$u->approval_status==='pending'&&(!$u->verification_required||$u->email_verified_at),422);DB::table('users')->where('id',$id)->update(['approval_status'=>$v['decision'],'rejection_reason'=>$v['decision']==='rejected'?$v['reason']:null,'updated_at'=>now()]);Support::audit('application-decision','user',$id,['approval_status'=>$u->approval_status],['approval_status'=>$v['decision']],$v['reason']??null);Support::notify([$id],'Application '.$v['decision'].': '.($v['reason']??''));Support::email($id,'LokaShop application decision','Your application was '.$v['decision'].'. '.($v['reason']??''));});return back()->with('success','Decision saved.');}
 public function form(){return view('guest-tools',['title'=>'Correct rejected application','forms'=>[['label'=>'Resubmit application','action'=>'/application/resubmit','fields'=>['email:email','password:password','business_name','id_document:file?','dti_document:file?','sec_document:file?','bir_document:file?']]]]);}
 public function resubmit(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required','business_name'=>'required|string|min:3|max:180','id_document'=>'nullable|file|mimes:jpg,jpeg,png,pdf|max:5120','dti_document'=>'nullable|file|mimes:jpg,jpeg,png,pdf|max:5120','sec_document'=>'nullable|file|mimes:jpg,jpeg,png,pdf|max:5120','bir_document'=>'nullable|file|mimes:jpg,jpeg,png,pdf|max:5120']);$u=DB::table('users')->where('email',mb_strtolower(trim($v['email'])))->first();if(!$u||!Hash::check($v['password'],$u->password)||$u->approval_status!=='rejected')Support::fail('email','Check credentials; only rejected applications can be resubmitted.');$site=config('app.site_kind');abort_unless(($site==='ecommerce'&&$u->role==='seller')||($site==='logistics'&&$u->role==='sorting_center'),403);
  $table=$u->role==='seller'?'seller_businesses':'sorting_centers';$name=trim($v['business_name']);if($u->role==='seller'&&$name!==DB::table('seller_businesses')->where('user_id',$u->id)->value('name'))Support::fail('business_name','The registered store name cannot be changed.');$norm=mb_strtolower($name);if($u->role==='seller'&&mb_strlen($name)>30)Support::fail('business_name','Shop name must be at most 30 characters.');if(DB::table($table)->whereRaw('LOWER(TRIM(name)) = ?',[$norm])->where('user_id','!=',$u->id)->exists())Support::fail('business_name','Name is already registered.');DB::transaction(function()use($u,$r,$table,$name,$norm){DB::table($table)->where('user_id',$u->id)->update(['name'=>$name,'name_normalized'=>$norm,'updated_at'=>now()]);foreach(['id_document','dti_document','sec_document','bir_document'] as $f)if($r->hasFile($f))DB::table('registration_documents')->insert(['user_id'=>$u->id,'kind'=>$f,'path'=>$r->file($f)->store('documents','local'),'created_at'=>now(),'updated_at'=>now()]);DB::table('users')->where('id',$u->id)->where('approval_status','rejected')->update(['approval_status'=>'pending','rejection_reason'=>null,'updated_at'=>now()]);});return redirect('/login')->with('success','Application resubmitted for review.');}
}
